#!/usr/bin/env python3
"""Render the defender-conditioned beneficiary v0.3 audit."""

from __future__ import annotations

import argparse
import json
from pathlib import Path


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--input-json",
        type=Path,
        default=Path(
            "data/processed/conditional_defender_game_v0_3/"
            "conditional_defender_game_v0_3.json"
        ),
    )
    parser.add_argument(
        "--output-html",
        type=Path,
        default=Path(
            "data/processed/conditional_defender_game_v0_3/"
            "conditional_defender_game_v0_3_audit.html"
        ),
    )
    return parser.parse_args()


TEMPLATE = r"""<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conditional defender game · v0.3</title><style>
:root{--bg:#071321;--panel:#101f32;--panel2:#14263c;--line:#304862;--text:#f3f7ff;--muted:#aebcd0;--cyan:#45e0d0;--pink:#ff51c7;--violet:#c58cff;--gold:#ffd052;--red:#ff6d5b;--blue:#438dff;--green:#65dda0;--orange:#ff9c43}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Pretendard,system-ui,sans-serif}main{max-width:1780px;margin:auto;padding:20px}h1{margin:0 0 5px;font-size:1.9rem}h2,h3{margin:0 0 8px}p{color:var(--muted);line-height:1.45}.notice{border-left:4px solid var(--gold);background:#192a42;padding:11px 14px;border-radius:7px;margin:10px 0}.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:9px 0}.grow{flex:1}select,button{font:inherit;color:var(--text);background:#192b43;border:1px solid #4a6483;border-radius:8px;padding:8px 11px}button.active{border-color:var(--gold);color:var(--gold);background:#2a2940}.layout{display:grid;grid-template-columns:minmax(780px,1fr) 610px;gap:15px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:14px}.pitch{display:block;width:100%;background:#17743a;border-radius:9px}.scrub{width:100%}.time{font-variant-numeric:tabular-nums}.legend{display:flex;gap:13px;flex-wrap:wrap;color:#cbd6e6;font-size:.82rem;margin-top:8px}.sw{display:inline-block;width:19px;border-top:4px solid;margin-right:5px}.status{display:inline-block;border-radius:99px;padding:4px 9px;font-size:.78rem;font-weight:800}.selected-status{background:#224b3f;color:#7ff0bc}.border-status{background:#4b4021;color:#ffe38c}.none-status{background:#4a3021;color:#ffca8e}.defender-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:9px 0}.defender-tabs button{text-align:left;min-height:64px}.defender-tabs small{display:block;color:var(--muted);margin-top:4px}.candidate-table{width:100%;border-collapse:collapse;font-size:.79rem;margin-top:8px}.candidate-table th{text-align:right;color:#aebcd0;padding:6px 4px;border-bottom:1px solid #415872}.candidate-table th:first-child,.candidate-table td:first-child{text-align:left}.candidate-table td{text-align:right;padding:7px 4px;border-bottom:1px solid #263d56}.candidate-table tbody tr{cursor:pointer}.candidate-table tbody tr:hover{background:#19304a}.candidate-table tbody tr.active{background:#203b55;outline:1px solid var(--violet)}.candidate-table .bad{color:#8190a4}.box{background:var(--panel2);border:1px solid #2d445f;border-radius:9px;padding:10px;margin-top:9px;line-height:1.45}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-top:9px}.metric{background:#152a40;border-radius:8px;padding:8px;min-height:66px}.metric span{font-size:.72rem;color:var(--muted)}.metric strong{display:block;font-size:1.02rem;margin-top:4px}.positive{color:var(--green)}.weak{color:var(--orange)}.components{display:grid;grid-template-columns:1fr 1fr;gap:7px}.component{background:#102033;padding:8px;border-radius:7px}.component b{float:right}.small{font-size:.81rem;color:var(--muted)}.warn{color:#ffd082}.branch-summary{width:100%;border-collapse:collapse;font-size:.82rem}.branch-summary td,.branch-summary th{padding:6px;border-bottom:1px solid #304862;text-align:left}.branch-summary tr.active{background:#203b55}@media(max-width:1250px){.layout{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(3,1fr)}}
</style></head><body><main><h1>Defender-conditioned off-ball game · v0.3</h1><p class="notice"><b>이번 페이지의 질문:</b> “누가 runner에게 반응하는가?”를 먼저 바꾸면, 그 수비수가 비우는 자원 때문에 살아나는 공격 옵션도 달라지는가? 수비수 후보는 beneficiary를 보지 않고 <b>t=0 runner 억제 책임</b>만으로 뽑았다.</p><div class="controls"><label>장면 <select class="scene"></select></label><button class="prev">← 이전</button><button class="next">다음 →</button><button class="play">▶ 재생</button><span class="time"></span><span class="grow"></span><span class="scene-status"></span></div><div class="defender-tabs"></div><div class="layout"><section class="panel"><div class="controls responses"><b>현재 수비수의 경로</b><button data-response="actual">실제 움직임</button><button data-response="runner" class="active">Runner 대응</button><button data-response="beneficiary">선택 후보 억제</button></div><svg class="pitch" viewBox="0 0 105 68"><rect width="105" height="68" fill="#17743a" stroke="white" stroke-width=".3"/><line x1="52.5" x2="52.5" y1="0" y2="68" stroke="white" stroke-width=".25"/><circle cx="52.5" cy="34" r="9.15" fill="none" stroke="white" stroke-width=".25"/><rect x="0" y="13.84" width="16.5" height="40.32" fill="none" stroke="white" stroke-width=".25"/><rect x="88.5" y="13.84" width="16.5" height="40.32" fill="none" stroke="white" stroke-width=".25"/><g class="static"></g><g class="moving"></g></svg><input class="scrub" type="range" min="0" value="0"><div class="legend"><span><i class="sw" style="border-color:var(--pink)"></i>runner 실제</span><span><i class="sw" style="border-color:var(--violet)"></i>beneficiary 실제</span><span><i class="sw" style="border-color:var(--gold)"></i>패스/전진 운반 옵션</span><span><i class="sw" style="border-color:white;border-top-style:dashed"></i>수비수 실제</span><span><i class="sw" style="border-color:var(--cyan)"></i>수비수 가상</span></div><p class="small">위 수비수 탭을 하나씩 바꾸며 beneficiary와 옵션 선이 함께 바뀌는지 본다. 전진 운반 옵션이면 금색 곡선이 볼 소유자의 feasible carry path다.</p></section><aside class="panel"><h2 class="title"></h2><p class="subtitle"></p><div class="metrics"><div class="metric"><span>Runner 대응 시 후보</span><strong class="vf"></strong></div><div class="metric"><span>후보 억제 시</span><strong class="vc"></strong></div><div class="metric"><span>후보 이득</span><strong class="benefit"></strong></div><div class="metric"><span>Runner 대응 시 Runner</span><strong class="rf"></strong></div><div class="metric"><span>Runner 비용</span><strong class="rcost"></strong></div></div><div class="box explanation"></div><div class="box"><h3>이 수비수에 조건부인 공격 옵션</h3><table class="candidate-table"><thead><tr><th>선수·옵션</th><th>대응 시</th><th>억제 시</th><th>옵션 이득</th><th>Runner 비용</th></tr></thead><tbody></tbody></table><p class="small">회색 행은 두 cross-cost 중 하나가 5% 미만인 약한 관계다. 행은 숨기지 않아 borderline 가설도 확인할 수 있다.</p></div><div class="box"><h3>Runner 담당 수비수별 결과</h3><table class="branch-summary"><thead><tr><th>수비수</th><th>runner-only 책임</th><th>잠정 beneficiary</th></tr></thead><tbody></tbody></table></div><div class="box"><h3>대응 → 후보 억제 시 구성 변화</h3><div class="components"><div class="component">수신/보유 확률 <b class="prob"></b></div><div class="component">Goal-danger 항 <b class="goal"></b></div><div class="component">경로/보유 생존 <b class="lane"></b></div><div class="component">수신 경쟁 <b class="race"></b></div></div></div><p class="small warn">값은 득점확률이 아니라 투명한 진단 proxy다. 수비수 선택과 beneficiary 선택의 논리적 순환을 끊었는지 검수하는 단계다.</p></aside></div></main><script id="data" type="application/json">__DATA__</script><script>
const DATA=JSON.parse(document.getElementById('data').textContent);let si=0,di=0,ci=0,mode='runner',fi=0,playing=false,timer=null;const $=s=>document.querySelector(s),S=()=>DATA[si],D=()=>S().branches[di],C=()=>D().candidates[ci],px=x=>52.5+S().attacking_direction*x,py=y=>34-y,fmt=v=>Number(v).toFixed(3),gain=v=>(v>=0?'+':'')+Number(v).toFixed(3);
function player(frame,id){let p=frame.players.find(x=>x[0]===id);return p?[p[2],p[3]]:null}function interp(ts,xy,t){if(t<=ts[0])return xy[0];if(t>=ts.at(-1))return xy.at(-1);let i=ts.findIndex(x=>x>=t),a=(t-ts[i-1])/(ts[i]-ts[i-1]);return[xy[i-1][0]+a*(xy[i][0]-xy[i-1][0]),xy[i-1][1]+a*(xy[i][1]-xy[i-1][1])]}function pathFor(response){return response.times_s.map((t,i)=>[t,...response.path_xy[i]])}function observedPath(id){return S().background_frames.filter(f=>f.time_s>=0).map(f=>[f.time_s,...player(f,id)])}function poly(path,color,dash='',width=.5,opacity=1){return`<polyline points="${path.map(p=>px(p[1])+','+py(p[2])).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}" stroke-dasharray="${dash}" opacity="${opacity}"/>`}
function response(){if(mode==='runner')return D().runner_follow_response;if(mode==='beneficiary')return C().best_cover_response;return null}function frameAtPeak(){let t=C().peak_time_s;return S().background_frames.reduce((a,b)=>Math.abs(b.time_s-t)<Math.abs(a.time_s-t)?b:a)}
function drawStatic(){let s=S(),d=D(),c=C(),peak=frameAtPeak(),html=poly(observedPath(s.runner_id),'#ff51c7','',.58)+poly(observedPath(c.player_id),'#c58cff','1 .55',.42,.78)+poly(d.actual_response.path_txy,'white','1 .55',.4,.88),r=response();if(r)html+=poly(pathFor(r),'#45e0d0','',.62);if(c.option_type==='forward_carry_space'&&c.carry_path_txy){html+=poly(c.carry_path_txy,'#ffd052','',.72,.95)}else if(peak.ball){html+=`<line x1="${px(peak.ball[0])}" y1="${py(peak.ball[1])}" x2="${px(c.event_x)}" y2="${py(c.event_y)}" stroke="#ffd052" stroke-width=".4" stroke-dasharray="1 .5"/>`}html+=`<circle cx="${px(c.event_x)}" cy="${py(c.event_y)}" r=".78" fill="none" stroke="#ffd052" stroke-width=".33"/><text x="${px(c.event_x)+1}" y="${py(c.event_y)-1}" fill="#fff0b5" font-size="1.45">${c.option_type==='forward_carry_space'?'carry endpoint':'receive'} @${c.peak_time_s.toFixed(2)}s</text>`;$('.static').innerHTML=html}
function actualAt(t){let p=D().actual_response.path_txy;if(t<=p[0][0])return[p[0][1],p[0][2]];if(t>=p.at(-1)[0])return[p.at(-1)[1],p.at(-1)[2]];let i=p.findIndex(x=>x[0]>=t),a=(t-p[i-1][0])/(p[i][0]-p[i-1][0]);return[p[i-1][1]+a*(p[i][1]-p[i-1][1]),p[i-1][2]+a*(p[i][2]-p[i-1][2])]}
function drawFrame(){let s=S(),d=D(),c=C(),f=s.background_frames[fi],t=f.time_s,r=response(),actual=t<0?player(f,d.defender_id):actualAt(t),virt=r?(t<0?actual:interp(r.times_s,r.path_xy,t)):actual,hidden=[s.runner_id,d.defender_id,c.player_id],html=f.players.filter(p=>!hidden.includes(p[0])).map(p=>`<circle cx="${px(p[2])}" cy="${py(p[3])}" r=".67" fill="${p[1]===s.attacking_team_id?'#ff6d5b':'#438dff'}" stroke="white" stroke-width=".12"><title>${s.names[p[0]]||p[0]}</title></circle>`).join('');if(f.ball)html+=`<circle cx="${px(f.ball[0])}" cy="${py(f.ball[1])}" r=".4" fill="#111" stroke="white" stroke-width=".14"/>`;let rp=player(f,s.runner_id),cp=player(f,c.player_id);html+=`<circle cx="${px(rp[0])}" cy="${py(rp[1])}" r="1.03" fill="#ff51c7" stroke="white" stroke-width=".2"><title>${s.runner_name}</title></circle>`;if(cp)html+=`<circle cx="${px(cp[0])}" cy="${py(cp[1])}" r=".95" fill="#ff6d5b" stroke="#c58cff" stroke-width=".43"><title>${c.player_name}</title></circle>`;html+=`<circle cx="${px(actual[0])}" cy="${py(actual[1])}" r="1.15" fill="none" stroke="white" stroke-width=".3"/>`;if(r)html+=`<circle cx="${px(virt[0])}" cy="${py(virt[1])}" r=".88" fill="#438dff" stroke="#45e0d0" stroke-width=".43"/>`;$('.moving').innerHTML=html;$('.scrub').value=fi;$('.time').textContent=`t=${t>=0?'+':''}${t.toFixed(2)}초`}
const reasonMap={no_legal_option:'합법 옵션 없음',not_attacking_option:'공격 진영 밖',no_follow_benefit:'옵션 이득 없음',no_runner_cost:'runner 비용 없음',follow_benefit_too_small:'옵션 이득 5% 미만',runner_cost_too_small:'runner 비용 5% 미만'};function renderCandidates(){let d=D();$('.candidate-table tbody').innerHTML=d.candidates.map((c,i)=>`<tr data-i="${i}" class="${i===ci?'active':''} ${c.eligible?'':'bad'}"><td><b>${c.player_name}</b><br><span class="small">${c.position||'?'} · ${c.option_type==='forward_carry_space'?'전진 운반 공간':'패스 수신'}</span></td><td>${fmt(c.follow_value)}</td><td>${fmt(c.best_cover_value)}</td><td>${gain(c.follow_benefit)}<br><span class="small">${(100*c.follow_benefit_fraction).toFixed(1)}%</span></td><td>${gain(c.runner_cost)}<br><span class="small">${(100*c.runner_cost_fraction).toFixed(1)}%</span></td></tr>`).join('');document.querySelectorAll('.candidate-table tbody tr').forEach(x=>x.onclick=()=>{ci=Number(x.dataset.i);renderAll()})}
function defenderTabs(){let s=S();$('.defender-tabs').innerHTML=s.branches.map((d,i)=>`<button data-di="${i}" class="${i===di?'active':''}"><b>${d.defender_name}</b>가 반응<small>${d.defender_position||'?'} · beneficiary ${d.selected_beneficiary_name||'없음'}</small></button>`).join('');document.querySelectorAll('.defender-tabs button').forEach(x=>x.onclick=()=>{di=Number(x.dataset.di);ci=Math.max(0,D().candidates.findIndex(c=>c.player_id===D().selected_beneficiary_id));renderAll()})}
function transition(a,b){return(100*a).toFixed(1)+'% → '+(100*b).toFixed(1)+'%'}function details(){let s=S(),d=D(),c=C(),selected=d.selected_beneficiary_id===c.player_id,reasons=c.rejection_reasons.map(x=>reasonMap[x]||x),f=c.follow_components,b=c.best_cover_components;$('.vf').textContent=fmt(c.follow_value);$('.vc').textContent=fmt(c.best_cover_value);$('.benefit').textContent=gain(c.follow_benefit);$('.benefit').className='benefit '+(c.follow_benefit>0?'positive':'weak');$('.rf').textContent=fmt(c.runner_follow_value);$('.rcost').textContent=gain(c.runner_cost);$('.rcost').className='rcost '+(c.runner_cost>0?'positive':'weak');let status=selected?'잠정 대표':c.eligible?'유효한 복수 옵션':'약함/제외',statusClass=selected||c.eligible?'selected-status':'border-status';$('.explanation').innerHTML=`<h3>${d.defender_name} → ${c.player_name} <span class="status ${statusClass}">${status}</span></h3>${c.option_type==='forward_carry_space'?`${s.ball_owner_name}가 동적 도달 영역 안의 전진 endpoint로 볼을 운반하는 옵션`:`${s.ball_owner_name}가 ${c.player_name}의 도달 가능한 수신 지점으로 패스하는 옵션`}<br>event <b>(${c.event_x.toFixed(1)}, ${c.event_y.toFixed(1)}) @ ${c.peak_time_s.toFixed(2)}초</b><br>두 수비 branch 평균 경로 차이 <b>${c.mean_response_separation_m.toFixed(1)}m</b> · 억제 메커니즘 <b>${c.suppression_mechanism}</b>${reasons.length?`<br><span class="warn">현재 판정: ${reasons.join(', ')}</span>`:'<br><span class="positive">두 방향의 상대 cross-cost가 모두 5% 이상이다.</span>'}`;$('.prob').textContent=transition(f.receive_probability,b.receive_probability);$('.goal').textContent=transition(f.goal_value,b.goal_value);$('.lane').textContent=transition(f.path_survival_probability,b.path_survival_probability);$('.race').textContent=transition(f.receiver_first_probability,b.receiver_first_probability);$('.title').textContent=`${s.runner_name} · ${d.defender_name}가 반응`;$('.subtitle').innerHTML=`볼 소유자 <b>${s.ball_owner_name}</b> · ${d.response_count}개 feasible response · runner-only 책임 <b>${(100*d.runner_only_responsibility).toFixed(1)}%p</b><br>goal-side follow 오차 <b>${d.runner_follow_anchor.tracking_error_m.toFixed(1)}m</b> · ${s.match_label}`}
function branchSummary(){let s=S();$('.branch-summary tbody').innerHTML=s.branches.map((d,i)=>`<tr class="${i===di?'active':''}"><td>${d.defender_name}</td><td>${(100*d.runner_only_responsibility).toFixed(1)}%p</td><td>${d.selected_beneficiary_name||'없음'}</td></tr>`).join('')}
function sceneStatus(){let s=S(),unique=[...new Set(s.branches.map(d=>d.selected_beneficiary_name).filter(Boolean))];$('.scene-status').innerHTML=unique.length>1?`<span class="status selected-status">수비수에 따라 beneficiary 변화</span>`:unique.length===1?`<span class="status border-status">동일 beneficiary · ${unique[0]}</span>`:`<span class="status none-status">식별 없음</span>`}
function renderAll(){drawStatic();drawFrame();renderCandidates();defenderTabs();details();branchSummary();sceneStatus()}function setScene(i){si=(Number(i)+DATA.length)%DATA.length;di=0;ci=Math.max(0,D().candidates.findIndex(c=>c.player_id===D().selected_beneficiary_id));fi=0;$('.scene').value=si;$('.scrub').max=S().background_frames.length-1;renderAll()}
function init(){let sel=$('.scene');sel.innerHTML=DATA.map((s,i)=>`<option value="${i}">${i+1}. ${s.runner_name} · frame ${s.onset_frame_id}</option>`).join('');sel.onchange=e=>setScene(e.target.value);$('.prev').onclick=()=>setScene(si-1);$('.next').onclick=()=>setScene(si+1);$('.scrub').oninput=e=>{fi=Number(e.target.value);drawFrame()};document.querySelectorAll('.responses button').forEach(b=>b.onclick=()=>{mode=b.dataset.response;document.querySelectorAll('.responses button').forEach(x=>x.classList.toggle('active',x===b));drawStatic();drawFrame()});$('.play').onclick=e=>{playing=!playing;e.target.textContent=playing?'❚❚ 일시정지':'▶ 재생';if(playing)timer=setInterval(()=>{fi=fi>=S().background_frames.length-1?0:fi+1;drawFrame()},70);else clearInterval(timer)};setScene(0)}init();
</script></body></html>"""


def main() -> None:
    args = parse_args()
    payload = json.loads(args.input_json.read_text(encoding="utf-8"))
    args.output_html.parent.mkdir(parents=True, exist_ok=True)
    args.output_html.write_text(
        TEMPLATE.replace("__DATA__", json.dumps(payload, ensure_ascii=False)),
        encoding="utf-8",
    )
    print(f"audit: {args.output_html.resolve()}")


if __name__ == "__main__":
    main()
